#include <iostream>
#include <stack>
#include <vector>

void buildMonotonicIncreasing(std::vector<int>& arr) {
    std::stack<int> s;
    for (int num : arr) {
        // Pop elements that are larger than the current element
        while (!s.empty() && s.top() > num) {
            s.pop();
        }
        s.push(num);
    }
}
